s.Calculation.properties.sourceRegistryHash={type:'string',pattern:'^[a-f0-9]{64}$'};s.Calculation.properties.attribution={type:'array',items:{$ref:'#/Attribution'}};
s.Calculation.required.push('sourceRegistryHash','attribution');
s.Preview=relocate(legacy.Preview);Object.assign(s.Preview.properties,{status:{type:'string',enum:['READY']},modelVersion:{type:'string',enum:['retirement-monthly-v4']},replayInput:{$ref:'#/ReplayInput'},calculation:{$ref:'#/Calculation'}});
