ai.setIn(['Explanation','properties','provenance','anyOf',0,'properties','sourceRegistry'],{type:'object',additionalProperties:false,required:['registryHash','attribution'],properties:{registryHash:{type:'string'},attribution:{type:'array',items:{$ref:'./source-snapshot.openapi.yaml#/Attribution'}}}});
